head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vKisCd = ""; // 조회조건 기업코드
scwin.vAcntclsDt = "";

///////// 2. 초기화 영역 /////////
/* ★Wcraft guide★    
스크립트 수작업 유의사항

*/
scwin.onpageload = function() {
};

scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
scwin.dts_RunRtDrft1_OnLoadError = function() {
    try {
        $c.win.alert(dts_RunRtDrft1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00220.dts_RunRtDrft1_OnLoadError" });
    }
};

scwin.dts_RunRtDrft1_OnLoadCompleted = function(rowcount) {
    try {
        if (dts_RunRtDrft1.errorMsg) {
            alert(dts_RunRtDrft1.errorMsg);
            return;
        }
        // 그리드 타이틀 세팅.
        scwin.setGrdTitle();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00220.dts_RunRtDrft1_OnLoadCompleted" });
    }
};

scwin.dts_RunRtDrft2_OnLoadError = function() {
    try {
        $c.win.alert(dts_RunRtDrft2);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00220.dts_RunRtDrft2_OnLoadError" });
    }
};

scwin.dts_RunRtDrft2_OnLoadCompleted = function(rowcount) {
    try {
        if (dts_RunRtDrft2.errorMsg) {
            alert(dts_RunRtDrft2.errorMsg);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00220.dts_RunRtDrft2_OnLoadCompleted" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * 최근 3년 결산일자 조회
 */
scwin.searchStdDt = async function() {
    const sbmOptions = {
        id : "sbm_dts_RunRtDrft1",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_RunRtDrft1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    scwin.dts_RunRtDrft1_OnLoadCompleted(dts_RunRtDrft1.getRowCount()); // 구 콜백 연결

};

/**
 * 가동률추이 조회
 */
scwin.searchRunRtDrft = async function() {
    // Lodaing~~~ 표시
    const sbmOptions = {
        id : "sbm_dts_RunRtDrft2",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_RunRtDrft2=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    scwin.dts_RunRtDrft2_OnLoadCompleted(dts_RunRtDrft2.getRowCount()); // 구 콜백 연결

};

///////// 5. 일반/업무 함수 영역 /////////
 // 조회조건 결산일자

/**
 *  화면 초기화
 */
scwin.init = function() {
    // 결산일자 조회

    // TODO Stage2: $c.frame 대체 불가(형제/절대 프레임 접근) — 프레임 구조 재설계 필요
    $c.frame.path("../frame_head").fn_SrchAcntclsDt();
};

/**
 *  데이터셋 초기화.
 */
scwin.initDs = function() {
    dts_RunRtDrft1.removeAll();
    dts_RunRtDrft2.removeAll();
};

/**
 *  조회조건 유효성 체크
 */
scwin.chkValid = function() {
    // 필수항목 체크.

    // TODO Stage2: $c.frame 대체 불가(형제/절대 프레임 접근) — 프레임 구조 재설계 필요
    scwin.vKisCd = $c.frame.path("../frame_head").fn_GetKisCd();

    // TODO Stage2: $c.frame 대체 불가(형제/절대 프레임 접근) — 프레임 구조 재설계 필요
    scwin.vAcntclsDt = $c.frame.path("../frame_head").fn_GetAcntclsDt();
    if (scwin.vKisCd === "" || scwin.vAcntclsDt === "") {
        return false;
    }
    return true;
};

/**
 * 가동률추이 조회
 */
scwin.search = function() {
    // 데이터셋 초기화
    scwin.initDs();

    // 조회조건 체크.
    if (!scwin.chkValid()) {
        return;
    }

    // Lodaing~~~ 표시

    // 최근 3년 결산일자 조회
    scwin.searchStdDt();
};

/**
 * 그리드 타이틀 세팅.
 */
scwin.setGrdTitle = function() {
    $c.cm.setColumnProp(grd_RunRtDrft, "YYYYMMDD1", "Name", $c.stf.FormatDateEx(dts_RunRtDrft1.getCellData(1, "STD_DT")));
    $c.cm.setColumnProp(grd_RunRtDrft, "YYYYMMDD2", "Name", $c.stf.FormatDateEx(dts_RunRtDrft1.getCellData(2, "STD_DT")));
    $c.cm.setColumnProp(grd_RunRtDrft, "YYYYMMDD3", "Name", $c.stf.FormatDateEx(dts_RunRtDrft1.getCellData(3, "STD_DT")));

    // 가동률추이 조회
    scwin.searchRunRtDrft();
};

/**
 *  엑셀파일다운로드
 */
scwin.excelDownload = function() {
    if (dts_RunRtDrft2.getRowCount() <= 0) {
        alert("조회된 데이터가 없습니다.");
        return;
    }
    $c.data.downloadGridViewExcel(grd_RunRtDrft, {fileName: "가동률추이", type: "8"});
};

scwin.gform_onload = function() {
    scwin.init();
};
